const listAutomationTestCases = `-- name: ListAutomationTestCases :many
SELECT c.id, c.name, c.case_kind, c.trigger, c.stubs, c.expect, c.seq, c.created_by, c.created_at
FROM pc.automation_test_cases c
WHERE c.org_id = $1 AND c.version_id = $2
ORDER BY c.seq
`

type ListAutomationTestCasesRow struct {
	ID        ids.UUID
	Name      string
	CaseKind  string
	Trigger   []byte
	Stubs     []byte
	Expect    []byte
	Seq       int32
	CreatedBy ids.UUID
	CreatedAt time.Time
}

func (q *Queries) ListAutomationTestCases(ctx context.Context, orgID ids.OrgID, versionID ids.UUID) ([]ListAutomationTestCasesRow, error) {
	rows, err := q.db.Query(ctx, listAutomationTestCases, orgID, versionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAutomationTestCasesRow{}
	for rows.Next() {
		var i ListAutomationTestCasesRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.CaseKind,
			&i.Trigger,
			&i.Stubs,
			&i.Expect,
			&i.Seq,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

